class Solution:
    def bubbleSort(self,nums):
        return self.bubbleSortHelper(nums,len(nums))
    def bubbleSortHelper(self, nums,n):
        if n==1:
            return nums
        for i in range(n-1):
            if nums[i]>nums[i+1]:
                nums[i],nums[i+1]=nums[i+1],nums[i]
        return self.bubbleSortHelper(nums,n-1)
